<script setup>
import {computed} from 'vue';import {money} from './domain.js';import {costSummary,canCost} from './finance.js';
const props=defineProps(['state','user','tenantId']);
const costs=computed(()=>canCost(props.state,props.user,props.tenantId)?(props.state.costs||costSummary(props.state,props.user)).filter(c=>c.tenantId===props.tenantId):[]);
</script>
<template><template v-if="costs.length"><div class="workflow-banner"><v-icon color="primary">mdi-chart-box-outline</v-icon><div><strong>Project costs · Admin and Superuser</strong><p>Approved commitments and additional expenses. Payments settle invoices and are not added to cost again.</p></div></div><template v-for="c in costs" :key="c.tenantId"><div class="stats-grid"><div class="stat-card primary-stat"><div class="stat-label">Total project cost</div><strong>{{money(c.total)}}</strong><span>Work orders + approved POs + additional approved expenses</span></div><div class="stat-card"><div class="stat-label">Net paid to vendors</div><strong>{{money(c.paid)}}</strong><span>Approved payment records only</span></div><div class="stat-card"><div class="stat-label">TDS recorded</div><strong>{{money(c.tds)}}</strong><span>Included in invoice settlements</span></div><div class="stat-card"><div class="stat-label">Outstanding invoices</div><strong>{{money(c.outstanding)}}</strong><span>Invoice value less approved net paid and TDS</span></div></div><div class="lower-grid"><section class="panel"><div class="panel-top"><h2>Cost composition</h2></div><table class="orders-table"><tbody><tr><td>Work-order commitments</td><td class="align-right">{{money(c.workOrders)}}</td></tr><tr><td>Approved purchased materials and rentals</td><td class="align-right">{{money(c.purchases)}}</td></tr><tr><td>Additional approved expenses</td><td class="align-right">{{money(c.additional)}}</td></tr><tr><td><strong>Project total</strong></td><td class="align-right"><strong>{{money(c.total)}}</strong></td></tr></tbody></table></section><section class="panel"><div class="panel-top"><div><h2>Materials and expense categories</h2><p>Order-linked expenses are excluded here to prevent duplication.</p></div></div><table class="orders-table"><tbody><tr v-for="(n,key) in c.categories" :key="key"><td>{{key}}</td><td class="align-right">{{money(n)}}</td></tr></tbody></table><div class="table-bottom">Recorded approved expenses: {{money(c.recordedExpenses)}}</div></section></div></template></template><section v-else class="panel"><div class="empty-state">The cost overview requires an Admin role and cost-view permissions, or Superuser access.</div></section></template>
